import{_ as e,o as n,c as i,a0 as r}from"./chunks/framework.DCluYYrN.js";const p=JSON.parse('{"title":"Apa itu KernelSU?","description":"","frontmatter":{},"headers":[],"relativePath":"id_ID/guide/what-is-kernelsu.md","filePath":"id_ID/guide/what-is-kernelsu.md"}'),t={name:"id_ID/guide/what-is-kernelsu.md"};function l(s,a,u,m,d,o){return n(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="apa-itu-kernelsu" tabindex="-1">Apa itu KernelSU? <a class="header-anchor" href="#apa-itu-kernelsu" aria-label="Permalink to &quot;Apa itu KernelSU?&quot;">​</a></h1><p>KernelSU adalah solusi root untuk perangkat GKI Android, ia bekerja dalam mode kernel dan memberikan izin root ke aplikasi userspace secara langsung di ruang kernel.</p><h2 id="fitur" tabindex="-1">Fitur <a class="header-anchor" href="#fitur" aria-label="Permalink to &quot;Fitur&quot;">​</a></h2><p>Fitur utama dari KernelSU adalah <strong>berbasis kernel</strong>. KernelSU bekerja dalam mode kernel, sehingga dapat menyediakan antarmuka kernel yang belum pernah kita miliki sebelumnya. Sebagai contoh, kita dapat menambahkan breakpoint perangkat keras ke proses apa pun dalam mode kernel; Kita dapat mengakses memori fisik dari proses apa pun tanpa diketahui oleh siapa pun; Kita dapat mencegat syscall apa pun di ruang kernel; dll.</p><p>Selain itu, KernelSU menyediakan <a href="./metamodule.html">sistem metamodule</a>, yang merupakan arsitektur yang dapat dipasang untuk manajemen modul. Tidak seperti solusi root tradisional yang mengintegrasikan logika mount ke dalam intinya, KernelSU mendelegasikan ini ke metamodules. Ini memungkinkan Anda untuk memasang metamodules (seperti <a href="https://github.com/tiann/KernelSU/tree/main/userspace/meta-overlayfs" target="_blank" rel="noreferrer">meta-overlayfs</a>) untuk menyediakan modifikasi systemless pada partisi <code>/system</code> dan partisi lainnya.</p><h2 id="bagaimana-cara-menggunakannya" tabindex="-1">Bagaimana cara menggunakannya <a class="header-anchor" href="#bagaimana-cara-menggunakannya" aria-label="Permalink to &quot;Bagaimana cara menggunakannya&quot;">​</a></h2><p>Silakan merujuk ke: <a href="./installation.html">Installation</a></p><h2 id="bagaimana-cara-men-buildnya" tabindex="-1">Bagaimana cara men-buildnya <a class="header-anchor" href="#bagaimana-cara-men-buildnya" aria-label="Permalink to &quot;Bagaimana cara men-buildnya&quot;">​</a></h2><p><a href="./how-to-build.html">How to build</a></p><h2 id="diskusi" tabindex="-1">Diskusi <a class="header-anchor" href="#diskusi" aria-label="Permalink to &quot;Diskusi&quot;">​</a></h2><ul><li>Telegram: <a href="https://t.me/KernelSU" target="_blank" rel="noreferrer">@KernelSU</a></li></ul>',11)])])}const h=e(t,[["render",l]]);export{p as __pageData,h as default};
